using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CheckBrillianceCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Austra/CheckBrillianceCustomDescription", order = 0)]
public class CheckBrillianceCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private Effect brillianceEffect;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		CheckBrillianceAction obj = battleAction as CheckBrillianceAction;
		string firstActionDescription = obj.ApplyEffectAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)).LowercaseFirst();
		string secondActionDescription = obj.CriticalConfuseMultiplierEffectAction.GetActionDescription(1).LowercaseFirst();
		return base.localizationManager.GetLocalizedIfHaveLessThanOtherwiseFormatted(brillianceEffect, firstActionDescription, secondActionDescription);
	}
}
